test "cli_env: empty argv yields the dflt defaults" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const gpa = arena_state.allocator();
    const argv = [_][]const u8{ "fx-env" };
    const o = try parsePosix(&argv, gpa);
    try std.testing.expectEqual(false, o.ignore);
    try std.testing.expectEqual(@as(usize, 0), o.sets.len);
    try std.testing.expect(o.unset == null);
}

